import http from 'http';
function main(): void {
  const events: string[] = [];
  const srv = http.createServer((req: any, res: any) => { res.end('x'); });
  srv.on('close', () => events.push('close'));
  srv.listen(0, '127.0.0.1', () => {
    http.get({ port: (srv.address() as any).port, host: '127.0.0.1' }, (res: any) => {
      res.on('data', () => {});
      res.on('end', () => { events.push('end'); srv.close(); events.push('closed-call:' + srv.listening); });
    });
  });
  setTimeout(() => console.log(events.join(',')), 400);
}
